package tmpx;
import java.util.*;
import com.fasterxml.jackson.annotation.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
public class TmpTest {
  static class W { @JsonValue @JsonInclude(value=JsonInclude.Include.NON_NULL, content=JsonInclude.Include.NON_NULL) final Map<String,Object> v; W(Map<String,Object> m){v=m;} }
  @Test void t() throws Exception {
    Map<String,Object> m = new LinkedHashMap<>(); m.put("a",null); m.put("b","x");
    assertEquals("{\"b\":\"x\"}", JsonMapper.builder().build().writeValueAsString(new W(m)));
  }
}
